NewUserStreakLossBannerHide: [ {
id: 336490004,
param: {
logicDesc: "预期效果：隐藏持续 2 关，给失败玩家更长的恢复窗口。 对比意图：与主方案生效 1 关对比，验证更长隐藏时长对留存与广告收益的影响。"
}
}, {
id: 336490003,
param: {
logicDesc: "预期效果：全程仅隐藏一次，控制广告曝光损失。 对比意图：与主方案重复触发开启对比，验证重复隐藏是否比单次隐藏更能提升连续失败玩家的留存。"
}
}, {
id: 336490002,
param: {
logicDesc: "预期效果：更晚触发 banner 隐藏，减少广告曝光损失。 对比意图：与主方案阈值=2 对比，验证更保守的隐藏阈值对留存与广告收益的影响。"
}
}, {
id: 336490001,
param: {
logicDesc: "旅行模式中记录玩家连续失败关卡数（死亡或步数耗尽均计为失败；冷启后重置、切换无尽模式后清零）。当连续失败数达到阈值时，进入下一关整关隐藏底部 banner 广告；本关结束（无论通关或失败）banner 恢复显示。若仍失败则计数继续累计、达到阈值倍数再次隐藏；若通关则计数清零、banner 正常展示。"
}
}, {
id: 336490005,
param: {
logicDesc: "预期效果：仅死亡计失败，步数耗尽不计，隐藏触发更严格。 对比意图：与主方案死亡+步数耗尽均计对比，验证失败判定范围对隐藏频率与体验的影响。"
}
} ],
