RainbowBlock: [ {
id: 335406005,
param: {
logicDesc: "本轮玩家操作触发盘面清屏（消除盘面上所有方块）后，下一轮出块必然包含彩虹块，替换本轮其中一个待放置块；非清屏轮维持主方案的按概率出现逻辑。用于将清屏爽感与彩虹块奖励绑定。"
}
}, {
id: 335406001,
param: {
rainbowBlockProbability: .1,
rainbowBlockSize: 1
}
}, {
id: 335406004,
param: {
logicDesc: "维护「距上次彩虹块出现的轮数」计数：连续 N 轮未出现彩虹块时，第 N+1 轮保底触发彩虹块必出，替换本轮其中一个待放置块；触发后计数归零，之后继续按主方案的概率随机出现。用于兜底低概率下的最少出现频次。"
}
}, {
id: 335406003,
param: {
logicDesc: "仅在本轮出块前的盘面权重高于配置阈值（盘面较危险）时，才允许彩虹块出现，具体是否出现继续沿用主方案的概率替换逻辑；盘面权重低于阈值时禁止彩虹块出现，本轮 3 块全部按普通方块流程生成。"
}
}, {
id: 335406002,
param: {
logicDesc: "在当前一局内累计触发的 Combo 次数达到指定门槛值时，下一轮出块必然包含彩虹块，替换本轮其中一个待放置块；未达到门槛前维持主方案的按概率出现逻辑。触发一次后 Combo 计数按该方案独立配置的规则重置或继续累积，不影响主方案其它规则。"
}
} ],
